(()=>{'use strict';const header=document.querySelector('main>header, main>.tools-top');if(!header)return;const bar=document.createElement('div');bar.id='globalGenerationStatus';bar.setAttribute('role','status');bar.setAttribute('aria-live','polite');bar.style.cssText='display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 32px;min-height:24px;border-bottom:1px solid #30404f;background:#14221f;color:#b5e3d2;font-size:14px;line-height:1.6';const dot=document.createElement('span');dot.textContent='●';dot.setAttribute('aria-hidden','true');const text=document.createElement('span');text.textContent='正在读取生成状态…';bar.append(dot,text);const spacer=document.createElement('div');spacer.id='globalStatusSpacer';spacer.setAttribute('aria-hidden','true');header.before(spacer);document.body.append(bar);bar.style.cssText+=';position:fixed;top:0;z-index:900;box-sizing:border-box;box-shadow:0 4px 14px #0004;padding:10px 18px;padding-top:max(10px,env(safe-area-inset-top));overflow-wrap:anywhere';function placeBar(){const main=document.querySelector('main'),r=main.getBoundingClientRect(),left=Math.max(0,r.left);bar.style.left=left+'px';bar.style.width=Math.max(0,Math.min(r.width,window.innerWidth-left))+'px';spacer.style.height=bar.getBoundingClientRect().height+'px';}const resize=new ResizeObserver(placeBar);resize.observe(bar);resize.observe(document.querySelector('main'));window.addEventListener('resize',placeBar);placeBar();let checking=false;function phase(graph){const nodes=Object.values(graph||{}),types=nodes.map(n=>n.class_type||'');if(types.includes('TextEncodeAceStepAudio1.5'))return '正在生成音乐 · ACE-Step';if(types.some(t=>t.startsWith('MMAudio')))return '正在生成视频同步音效';if(types.includes('MiniMaxH3ReferenceToVideo'))return '正在生成视频 · 多图参考';if(types.includes('MiniMaxH3ImageToVideo'))return '正在生成视频 · 首帧 / 首尾帧';if(types.includes('ImageUpscaleWithModel'))return types.includes('LoadVideo')?'正在放大视频':'正在高清放大图片';if(types.some(t=>/MiniMax|Wan|Video/.test(t)))return '正在生成视频';if(types.includes('TextEncodeQwenImageEditPlus'))return '正在图生图';return '正在生成图片';}
function h3Stage(graph){const nodes=Object.values(graph||{}),second=nodes.some(n=>n.class_type==='LoadH3ToolLatent')&&nodes.some(n=>n.class_type==='MMH3UltimateUpscale'),first=nodes.some(n=>n.class_type==='SaveH3ToolLatent');if(!first&&!second)return null;const sample=nodes.find(n=>n.class_type===(second?'MMH3UltimateUpscale':'SamplerCustomAdvanced')),link=sample?.inputs?.sigmas,split=Array.isArray(link)?graph[String(link[0])]:null;let steps;if(split?.class_type==='SplitSigmas'){const schedule=graph[String(split.inputs.sigmas?.[0])],total=Number(schedule?.inputs?.steps),high=Number(split.inputs.step);if(Number.isFinite(total)&&Number.isFinite(high))steps=link[1]===1?Math.max(0,total-high):Math.min(total,high);}return {label:'正在生成视频 · H3 '+(second?'二采':'一采')+(steps?' · '+(second?'每块':'')+steps+'步':''),steps,second};}
function details(entry,freshJob){const graph=entry?.[2]||{},nodes=Object.values(graph),prefix=nodes.find(n=>/^(Save(Image|Video|Audio.*)|VHS_VideoCombine)$/.test(n.class_type))?.inputs?.filename_prefix||'',jobId=prefix.match(/[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}/gi)?.at(-1);let job,resource='';if(typeof data!=='undefined'){for(const c of data.characters||[]){const found=[c.portraitJob,c.frontJob,c.identityPortrait,...Object.values(c.oneClick?.tasks||{}),...(c.multi||[]).flatMap(v=>Object.values(v.jobs||{}))].find(j=>j&&(j.prompt_id===entry[1]||j.id===jobId));if(found){job=found;resource=c.name+' · '+(({portrait:'大头像',front:'全身正面',left:'侧面',back:'背面'})[found.angle||found.mode]||'人物图');break;}}if(!job)for(const s of data.scenes||[]){const found=[...Object.values(s.jobs||{}),...(s.sceneVersions||[])].find(j=>j&&(j.prompt_id===entry[1]||j.id===jobId));if(found){job=found;resource='场景「'+s.name+'」';break;}}if(!job)for(const s of [...(data.shots||[]),...(data.shotScript?.generation_clips||[])]){const entries=[s.videoJob,s.frameImages?.first?.job,s.frameImages?.last?.job];const found=entries.find(j=>j&&(j.prompt_id===entry[1]||j.id===jobId));if(found){job=found;resource=(s.shot_id||s.clip_id||'分镜')+' · '+(s.title||'');break;}}if(!resource){const match=(data.characters||[]).find(c=>prefix.includes('/'+(c.id||c.character_id)+'/'));if(match)resource=match.name;else{const scene=(data.scenes||[]).find(s=>prefix.includes('/'+(s.id||s.scene_id)+'/'));if(scene)resource='场景「'+scene.name+'」';else{const shot=(data.shots||[]).find(s=>prefix.includes('/'+s.shot_id+'/'));if(shot)resource=shot.shot_id+' · '+(shot.title||'');}}}}
const h3=h3Stage(graph);let label=h3?h3.label:phase(graph);if(job?.mode==='portrait')label='正在生成大头像'+(job.batch_size===4?' · 一批4张':'');else if(job?.angle)label='正在生成'+({front:'全身正面',left:'侧面',back:'背面',portrait:'大头像'})[job.angle];const sampler=nodes.find(n=>n.class_type==='KSampler'||n.class_type==='BasicScheduler'),steps=sampler?.inputs?.steps;const progress=(freshJob||job)?.progress;if(!h3&&progress?.step!=null&&progress?.total_steps)label+=' · 第'+progress.step+'/'+progress.total_steps+'步';else if(!h3&&steps)label+=' · '+steps+'步';return label+(resource?' · '+resource:'');}
function timeLabel(seconds){const n=Math.max(0,Math.round(seconds)),h=Math.floor(n/3600),m=Math.floor(n%3600/60),r=n%60;return(h?h+'小时':'')+(m?m+'分':'')+(!h&&(r||!m)?r+'秒':'');}
async function upscaleBatchStatus(){if(typeof data==='undefined'||!data.project_id)return false;const b=await fetch('/api/shot-upscale?project_id='+encodeURIComponent(data.project_id),{cache:'no-store',signal:AbortSignal.timeout(4000)}).then(r=>r.ok?r.json():[]).then(bs=>bs.find(b=>b.status==='running')).catch(()=>null);if(!b)return false;const jobs=await fetch('/api/tools/jobs',{cache:'no-store',signal:AbortSignal.timeout(4000)}).then(r=>r.ok?r.json():[]);const active=b.items.find(i=>i.status==='running'),job=jobs.find(j=>j.id===active?.job_id),pending=b.items.filter(i=>i.status==='queued');const done=b.items.filter(i=>['completed','skipped'].includes(i.status)).length,elapsed=(Date.now()-Date.parse(b.created_at))/1000;const samples=jobs.filter(j=>j.kind==='upscale-video'&&j.status==='completed'&&j.upscale_target===b.target&&j.started_at&&j.finished_at&&j.duration>0).map(j=>(Date.parse(j.finished_at)-Date.parse(j.started_at))/1000/j.duration).filter(x=>x>0);let rate=samples.length?samples.reduce((a,v)=>a+v,0)/samples.length:null;const processingElapsed=job?.started_at?(Date.now()-Date.parse(job.started_at))/1000:0;if(job?.completed_segments>0&&job.segment_files?.length&&job.duration>0)rate=processingElapsed/(job.completed_segments/job.segment_files.length)/job.duration;let current=job?.upscale_remaining_seconds;if(!Number.isFinite(current)&&job&&rate)current=Math.max(0,rate*job.duration-processingElapsed);let remaining=Number.isFinite(current)?current:active?null:0;for(const i of pending){const source=jobs.find(j=>j.shot_upscale_binding?.video_id===i.video_id),shot=(data.shots||[]).find(x=>(x.shot_id||x.id)===i.target_id),duration=source?.duration||shot?.duration;if(!rate||!duration){remaining=null;break;}if(remaining!==null)remaining+=rate*duration;}text.textContent='分镜放大 '+done+'/'+b.items.length+(active?' · '+active.target_id:'')+' · 已用 '+timeLabel(elapsed)+' · 整批预计剩余 '+(remaining===null?'计算中':timeLabel(Math.max(5,remaining+pending.length*3+(job?5:0))))+(job?.progress?.label?' · '+job.progress.label:pending[0]?.phase?' · '+pending[0].phase:'');dot.style.color='#8ee4c2';bar.style.background='#142923';return true;}
async function update(){if(checking)return;checking=true;try{const port=typeof tab!=='undefined'&&(tab===2||tab===4)&&typeof videoGenerationPort==='function'?videoGenerationPort():Number(localStorage.getItem('frame-comfy-port')||8188);const local=await fetch('/api/audio/active',{cache:'no-store',signal:AbortSignal.timeout(5000)}).then(r=>r.ok?r.json():null).catch(()=>null);if(local){text.textContent=(local.target_id||'')+' · '+(local.phase||'正在生成音效')+' · 已用 '+Math.max(0,Math.floor((Date.now()-Date.parse(local.started_at||local.created_at))/1000))+'秒';dot.style.color='#8ee4c2';bar.style.background='#142923';return;}if(await upscaleBatchStatus())return;const r=await fetch('/api/comfy/queue?port='+port,{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const q=await r.json(),running=q.queue_running||[],pending=q.queue_pending||[];let message=running.length?details(running[0])+' · 排队 '+pending.length+' 项':pending.length?'等待开始生成 · 排队 '+pending.length+' 项':'当前空闲 · 没有正在生成或排队的任务';if(running.length){const graph=running[0]?.[2]||{},nodes=Object.values(graph),prefix=nodes.find(n=>/^(Save(Image|Video|Audio.*)|VHS_VideoCombine)$/.test(n.class_type))?.inputs?.filename_prefix||'',jobId=prefix.match(/[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}/gi)?.at(-1);if(jobId){const route=/(?:^|\/)H3Tools\//.test(prefix)?'/api/h3-tools/'+jobId:/\/Audio\//.test(prefix)?'/api/audio/'+jobId:/\/Tools\//.test(prefix)?'/api/tools/jobs/'+jobId:/\/Videos\//.test(prefix)?'/api/video/'+jobId:'/api/front-image/'+jobId;try{const response=await fetch(route,{cache:'no-store',signal:AbortSignal.timeout(8000)});if(response.ok){const job=await response.json(),t=job.timing||(job.first_estimate?{elapsed_seconds:job.elapsed_seconds,remaining_range_seconds:job.first_estimate.remaining_range_seconds}:{});message=details(running[0],job)+' · 排队 '+pending.length+' 项';const started=Date.parse(job.stage_started_at||job.started_at||job.created_at);if(Number.isFinite(started))message+=' · 已用 '+timeLabel(Number.isFinite(t.elapsed_seconds)?t.elapsed_seconds:(Date.now()-started)/1000);let seconds=t.remaining_seconds;if(!Number.isFinite(seconds)&&t.remaining_range_seconds)seconds=(t.remaining_range_seconds[0]+t.remaining_range_seconds[1])/2;if(Number.isFinite(seconds)){const n=Math.max(5,Math.round(seconds)),m=Math.floor(n/60);message+=' · 预计还需约 '+(m?m+'分'+(n%60?n%60+'秒':''):n+'秒')+'（含处理保存）';}else message+=job.first_estimate?.overdue?' · 已超出历史估算，仍在处理中':' · 预计剩余：估算中';if(job.progress?.label)message+=' · '+job.progress.label;}}catch{}}}if(running.length>1)message+=' · 共'+running.length+'项运行中';if(text.textContent!==message)text.textContent=message;dot.style.color=running.length?'#8ee4c2':'#8b9dac';bar.style.background=running.length?'#142923':'#141e29';}catch{const message='生成服务未连接 · 请检查 ComfyUI 是否启动';if(text.textContent!==message)text.textContent=message;dot.style.color='#d7b77a';}finally{checking=false;}}update();setInterval(update,3000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)update();});})();
